//! Prepare a derived encrypted FTS snapshot without publishing it.
//! A caller must validate the source revision again while publishing.
use super::*;
use serde_json::Value;
use std::os::{fd::AsRawFd,unix::fs::{DirBuilderExt,OpenOptionsExt,MetadataExt}};
use std::io::{Read,Write};

pub struct SearchStage { path: std::path::PathBuf, source_token:(i64,i64), generation:String, checkpoint:i64, owned:(u64,u64), lock_path:std::path::PathBuf, lock_owned:(u64,u64), _lock:std::fs::File, file:std::fs::File, published:std::sync::atomic::AtomicBool, private_dir:Option<(std::path::PathBuf,(u64,u64))> }
/// The stage is disposable until publication. SQLite cannot create a DELETE
/// journal next to /dev/fd, so MEMORY is used only before publication. After a
/// crash an incomplete stage is discarded/rebuilt, never treated as active.
fn connect_disposable(file:&std::fs::File,password:&str)->Result<Connection,String>{
 #[cfg(target_os="macos")] let path=format!("/dev/fd/{}",file.as_raw_fd());
 #[cfg(target_os="linux")] let path=format!("/proc/self/fd/{}",file.as_raw_fd());
 #[cfg(not(any(target_os="macos",target_os="linux")))] return Err("Неподдерживаемая система".into());
 let db=Connection::open_with_flags(path,rusqlite::OpenFlags::SQLITE_OPEN_READ_WRITE).map_err(|e|e.to_string())?;db.pragma_update(None,"key",password).map_err(|e|e.to_string())?;let version:String=db.query_row("PRAGMA cipher_version",[],|r|r.get(0)).map_err(|e|e.to_string())?;if version.is_empty(){return Err("SQLCipher недоступен".into())}let mode:String=db.query_row("PRAGMA journal_mode=MEMORY",[],|r|r.get(0)).map_err(|e|e.to_string())?;if !mode.eq_ignore_ascii_case("memory"){return Err("Временный журнал недоступен".into())}db.pragma_update(None,"temp_store","MEMORY").map_err(|e|e.to_string())?;Ok(db)
}
impl SearchStage {
 pub fn path(&self)->&Path{&self.path}
 /// Duplicate the already pinned descriptor; never reopen an untrusted path.
 pub fn pinned_file(&self)->Result<std::fs::File,String>{self.file.try_clone().map_err(|e|e.to_string())}
 pub fn source_token(&self)->(i64,i64){self.source_token}
 pub(crate) fn rebase_source_token(&mut self,old:(i64,i64),new:(i64,i64))->Result<(),String>{if self.source_token!=old{return Err("Пространство изменилось во время подготовки поиска".into())}self.source_token=new;Ok(())}
 pub fn generation(&self)->&str{&self.generation}
 pub fn checkpoint(&self)->i64{self.checkpoint}
}
impl SearchStage {
 /// Reopen a fully prepared stage left by an interrupted migration. Incomplete
 /// stages are rejected; callers replay the durable journal before publishing.
 pub fn resume(source:&Vault,path:&Path,password:&str)->Result<Self,String>{
  let filename=path.file_name().and_then(|v|v.to_str()).ok_or("invalid stage")?;let id=filename.strip_prefix(".atlas-search-stage-").ok_or("invalid stage")?;if id.len()!=32||!id.bytes().all(|v|v.is_ascii_hexdigit()){return Err("invalid stage".into())}
  let lock_path=path.with_file_name(format!("{filename}.lock"));let mut lock=std::fs::OpenOptions::new().read(true).write(true).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC).open(&lock_path).map_err(|e|e.to_string())?;if unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_EX|libc::LOCK_NB)}!=0{return Err("Подготовка уже выполняется".into())}let lm=lock.metadata().map_err(|e|e.to_string())?;let mut marker=String::new();lock.read_to_string(&mut marker).map_err(|e|e.to_string())?;let expected=marker.split_once(':').and_then(|(a,b)|Some((a.parse::<u64>().ok()?,b.parse::<u64>().ok()?))).ok_or("invalid stage marker")?;let meta=std::fs::symlink_metadata(path).map_err(|e|e.to_string())?;if !meta.is_file()||(meta.dev(),meta.ino())!=expected{return Err("Файл индекса изменился".into())}
  let file=std::fs::OpenOptions::new().read(true).write(true).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC).open(path).map_err(|e|e.to_string())?;let pinned=file.metadata().map_err(|e|e.to_string())?;if (pinned.dev(),pinned.ino())!=expected{return Err("Файл индекса изменился".into())}let db=connect_disposable(&file,password)?;let (complete,identity,generation,checkpoint):(i64,String,String,i64)=db.query_row("SELECT complete,source_identity,generation,checkpoint FROM atlas_fts_stage_meta WHERE id=1",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?))).map_err(|_|"Подготовка индекса не завершена")?;if complete!=1||generation!=id{return Err("Подготовка индекса не завершена".into())}if identity!=source.workspace_identity()?{return Err("Индекс относится к другому пространству".into())}source.pending_search_updates(1)?;let check:String=db.query_row("PRAGMA quick_check",[],|r|r.get(0)).map_err(|e|e.to_string())?;if check!="ok"{return Err("Подготовленный индекс повреждён".into())}drop(db);let source_token=source.semantic_mutation_token()?;Ok(Self{path:path.to_owned(),source_token,generation,checkpoint,owned:expected,lock_path,lock_owned:(lm.dev(),lm.ino()),_lock:lock,file,published:std::sync::atomic::AtomicBool::new(meta.nlink()>1),private_dir:None})
 }
}
impl SearchStage {
 /// Replay a bounded dirty batch. A crash before acknowledgement safely replays it.
 pub fn replay_pending(&mut self,source:&Vault,password:&str,limit:usize)->Result<usize,String>{self.replay_pending_with(source,password,limit,||Ok(()))}
 fn replay_pending_with(&mut self,source:&Vault,password:&str,limit:usize,after_commit:impl FnMut()->Result<(),String>)->Result<usize,String>{self.replay_pending_guarded_with(source,password,limit,after_commit,||Ok(()))}
 pub fn replay_pending_guarded(&mut self,source:&Vault,password:&str,limit:usize,verify:impl Fn()->Result<(),String>)->Result<usize,String>{self.replay_pending_guarded_with(source,password,limit,||Ok(()),verify)}
 fn replay_pending_guarded_with(&mut self,source:&Vault,password:&str,limit:usize,after_commit:impl FnMut()->Result<(),String>,verify:impl Fn()->Result<(),String>)->Result<usize,String>{verify()?;if self.published.load(std::sync::atomic::Ordering::Acquire){return Err("Индекс уже опубликован".into())}let db=connect_disposable(&self.file,password)?;let (applied,checkpoint)=replay_pending_db_with(source,&db,limit,after_commit,verify,true)?;if let Some(seq)=checkpoint{self.checkpoint=seq;}self.source_token=source.semantic_mutation_token()?;Ok(applied)}
 pub fn synchronize_checkpoint(&mut self,source:&Vault,password:&str)->Result<(),String>{if self.published.load(std::sync::atomic::Ordering::Acquire){return Err("Индекс уже опубликован".into())}let db=connect_disposable(&self.file,password)?;if let Some(seq)=synchronize_checkpoint_db(source,&db,&||Ok(()),true)?{self.checkpoint=seq;}self.source_token=source.semantic_mutation_token()?;Ok(())}
}
/// Replay against an already opened SQLCipher connection without storing the key.
/// A source/secondary pair must be protected against concurrent replay by caller.
pub fn replay_pending_db(source:&Vault,derived:&Connection,limit:usize)->Result<usize,String>{replay_pending_db_guarded(source,derived,limit,||Ok(()))}
/// Caller verifies removable-media identity and cancellation immediately before each commit.
pub fn replay_pending_db_guarded(source:&Vault,derived:&Connection,limit:usize,verify:impl Fn()->Result<(),String>)->Result<usize,String>{Ok(replay_pending_db_with(source,derived,limit,||Ok(()),verify,false)?.0)}
fn replay_pending_db_with(source:&Vault,derived:&Connection,limit:usize,mut after_commit:impl FnMut()->Result<(),String>,verify:impl Fn()->Result<(),String>,disposable:bool)->Result<(usize,Option<i64>),String>{
 use rusqlite::OptionalExtension;
 let (identity,generation,checkpoint):(String,String,i64)=derived.query_row("SELECT source_identity,generation,checkpoint FROM atlas_fts_stage_meta WHERE id=1 AND complete=1",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|_|"Индекс повреждён")?;if identity!=source.workspace_identity()?{return Err("Индекс относится к другому пространству".into())}
 let active:bool=source.db.query_row("SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='atlas_fts_active')",[],|r|r.get(0)).map_err(|e|e.to_string())?;if active{let (active_identity,active_generation,active_checkpoint):(String,String,i64)=source.db.query_row("SELECT source_identity,generation,checkpoint FROM atlas_fts_active WHERE singleton=1",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|_|"Индекс не активирован")?;if active_identity!=identity||active_generation!=generation||checkpoint<active_checkpoint{return Err("Копия индекса устарела; требуется перестроение".into())}}
 if checkpoint>source.search_journal_sequence()?{return Err("Копия индекса устарела; требуется перестроение".into())}
 let pending=source.all_pending_search_updates()?;let mut applied=0;derived.execute_batch("CREATE TABLE IF NOT EXISTS atlas_fts_applied(id TEXT PRIMARY KEY,generation INTEGER NOT NULL)").map_err(|e|e.to_string())?;
 for (id,version) in &pending{
  let existing:Option<i64>=derived.query_row("SELECT generation FROM atlas_fts_applied WHERE id=?1",[id],|r|r.get(0)).optional().map_err(|e|e.to_string())?;if existing==Some(*version){continue}if applied>=limit.min(256){break}
  let token=source.semantic_mutation_token()?;
  let size:Option<i64>=source.db.query_row("SELECT octet_length(id)+octet_length(title)+octet_length(body)+octet_length(description) FROM search_index WHERE id=?1",[id],|r|r.get(0)).optional().map_err(|e|e.to_string())?;if size.is_some_and(|n|n>32*1024*1024){return Err("Текст одного объекта превышает предел 32 МиБ".into())}
  let source_row:Option<(String,String,String,String)>=source.db.query_row("SELECT id,title,body,description FROM search_index WHERE id=?1",[id],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?))).optional().map_err(|e|e.to_string())?;
  let object:Option<(String,String)>=source.db.query_row("SELECT id,title FROM objects WHERE id=?1",[id],|r|Ok((r.get(0)?,r.get(1)?))).optional().map_err(|e|e.to_string())?;
  let trashed:bool=source.db.query_row("SELECT EXISTS(SELECT 1 FROM trash WHERE id=?1)",[id],|r|r.get(0)).map_err(|e|e.to_string())?;
  let tx=derived.unchecked_transaction().map_err(|e|e.to_string())?;
  tx.execute("DELETE FROM objects WHERE id=?1",[id]).map_err(|e|e.to_string())?;if let Some((a,b))=object.as_ref(){tx.execute("INSERT INTO objects VALUES(?1,?2)",params![a,b]).map_err(|e|e.to_string())?;}tx.execute("DELETE FROM trash WHERE id=?1",[id]).map_err(|e|e.to_string())?;if trashed&&object.is_some(){tx.execute("INSERT INTO trash VALUES(?1)",[id]).map_err(|e|e.to_string())?;}
  tx.execute("DELETE FROM search_index WHERE id=?1",[id]).map_err(|e|e.to_string())?;tx.execute("DELETE FROM search_chunks WHERE object_id=?1",[id]).map_err(|e|e.to_string())?;
  if let Some((a,b,c,d))=source_row.filter(|_|object.is_some()){tx.execute("INSERT INTO search_index(id,title,body,description) VALUES(?1,?2,?3,?4)",params![a,b,c,d]).map_err(|e|e.to_string())?;tx.execute("INSERT INTO search_chunks(object_id,start,field,content) VALUES(?1,-1,'title',?2)",params![a,b]).map_err(|e|e.to_string())?;for(field,text)in [("body",c.as_str()),("description",d.as_str())]{for(start,part)in chunks(text){tx.execute("INSERT INTO search_chunks(object_id,start,field,content) VALUES(?1,?2,?3,?4)",params![a,start as i64,field,part]).map_err(|e|e.to_string())?;}}}
  tx.execute("INSERT INTO atlas_fts_applied(id,generation) VALUES(?1,?2) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation",params![id,version]).map_err(|e|e.to_string())?;
  if source.semantic_mutation_token()?!=token{return Err("Пространство изменилось во время обновления поиска".into())}verify()?;tx.commit().map_err(|e|e.to_string())?;after_commit()?;applied+=1;
 }
 Ok((applied,synchronize_checkpoint_db(source,derived,&verify,disposable)?))
}
fn synchronize_checkpoint_db(source:&Vault,db:&Connection,verify:&impl Fn()->Result<(),String>,disposable:bool)->Result<Option<i64>,String>{
 use rusqlite::OptionalExtension;
 let (identity,generation,derived_checkpoint):(String,String,i64)=db.query_row("SELECT source_identity,generation,checkpoint FROM atlas_fts_stage_meta WHERE id=1 AND complete=1",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|_|"Индекс повреждён")?;if identity!=source.workspace_identity()?{return Err("Индекс относится к другому пространству".into())}
 let pending=source.all_pending_search_updates()?;let token=source.semantic_mutation_token()?;let seq=source.search_journal_sequence()?;
 let active:bool=source.db.query_row("SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='atlas_fts_active')",[],|r|r.get(0)).map_err(|e|e.to_string())?;
 if active{let published:i64=source.db.query_row("SELECT checkpoint FROM atlas_fts_active WHERE singleton=1 AND generation=?1",[&generation],|r|r.get(0)).map_err(|_|"Индекс изменился")?;if derived_checkpoint<published{return Err("Копия индекса устарела; требуется перестроение".into())}}
 if derived_checkpoint>seq||(pending.is_empty()&&derived_checkpoint!=seq){return Err("Копия индекса устарела; требуется перестроение".into())}
 for (id,version) in &pending{let applied:Option<i64>=db.query_row("SELECT generation FROM atlas_fts_applied WHERE id=?1",[id],|r|r.get(0)).optional().map_err(|e|e.to_string())?;if applied!=Some(*version){return Ok(None)}}
 verify()?;let changed=db.execute("UPDATE atlas_fts_stage_meta SET checkpoint=?1 WHERE id=1 AND generation=?2",params![seq,generation]).map_err(|e|e.to_string())?;if changed!=1{return Err("Индекс изменился".into())}if disposable{let mode:String=db.query_row("PRAGMA journal_mode=DELETE",[],|r|r.get(0)).map_err(|e|e.to_string())?;if !mode.eq_ignore_ascii_case("delete"){return Err("Не удалось подготовить журнал индекса".into())}}
 if source.semantic_mutation_token()?!=token{return Err("Пространство изменилось во время обновления поиска".into())}
 let tx=source.db.unchecked_transaction().map_err(|e|e.to_string())?;let now:i64=tx.query_row("SELECT seq FROM atlas_fts_sequence WHERE id=1",[],|r|r.get(0)).map_err(|e|e.to_string())?;if now!=seq{return Err("Пространство изменилось во время обновления поиска".into())}
 for (id,version) in &pending{if tx.execute("DELETE FROM atlas_fts_dirty WHERE id=?1 AND generation=?2",params![id,version]).map_err(|e|e.to_string())?!=1{return Err("Пространство изменилось во время обновления поиска".into())}}
 let remaining:bool=tx.query_row("SELECT EXISTS(SELECT 1 FROM atlas_fts_dirty)",[],|r|r.get(0)).map_err(|e|e.to_string())?;if remaining{return Err("Пространство изменилось во время обновления поиска".into())}
 if active&&tx.execute("UPDATE atlas_fts_active SET checkpoint=?1 WHERE singleton=1 AND generation=?2",params![seq,generation]).map_err(|e|e.to_string())?!=1{return Err("Индекс изменился".into())}
 verify()?;tx.commit().map_err(|e|e.to_string())?;Ok(Some(seq))
}

#[cfg(feature="test-hook")]
fn search_publish_barrier(point:&str){if let Some(dir)=std::env::var_os("ATLAS_TEST_SEARCH_PUBLISH_BARRIER"){let dir=Path::new(&dir);let _=std::fs::write(dir.join(format!("{point}-ready")),b"ready");while !dir.join(format!("{point}-go")).exists(){std::thread::sleep(std::time::Duration::from_millis(10));}}}
impl SearchStage {
 /// Publish without replacing a pre-existing file. Caller must serialize all
 /// workspace mutations with `guard` until this method returns.
 pub fn publish<G>(&self,source:&Vault,destination:&Path,guard:impl FnOnce()->Result<G,String>)->Result<(),String>{
  let _guard=guard()?;
  if !source.pending_search_updates(1)?.is_empty(){return Err("Поисковый индекс ещё обновляется".into())}
  if source.semantic_mutation_token()?!=self.source_token||source.search_journal_sequence()?!=self.checkpoint{return Err("Пространство изменилось во время подготовки поиска".into())}
  let stage=std::fs::symlink_metadata(&self.path).map_err(|e|e.to_string())?;if !stage.is_file()||(stage.dev(),stage.ino())!=self.owned{return Err("Файл индекса изменился".into())}
  #[cfg(feature="test-hook")] search_publish_barrier("before");
  match std::fs::hard_link(&self.path,destination){Ok(())=>{},Err(e) if e.kind()==std::io::ErrorKind::AlreadyExists=>{let existing=std::fs::symlink_metadata(destination).map_err(|e|e.to_string())?;if !existing.is_file()||(existing.dev(),existing.ino())!=self.owned{return Err("Файл назначения уже существует".into())}},Err(e)=>return Err(e.to_string())}
  self.published.store(true,std::sync::atomic::Ordering::Release);
  #[cfg(feature="test-hook")] search_publish_barrier("after");
  let published=std::fs::symlink_metadata(destination).map_err(|e|e.to_string())?;if !published.is_file()||(published.dev(),published.ino())!=self.owned{return Err("Опубликованный индекс изменился".into())}
  let parent=destination.parent().ok_or("Папка недоступна")?;std::fs::File::open(parent).and_then(|f|f.sync_all()).map_err(|e|format!("Индекс опубликован, но сохранение не подтверждено: {e}"))?;Ok(())
 }
}
impl SearchStage {
 /// Search only a fully replayed stage; stale results are never returned.
 pub fn search(&self,source:&Vault,password:&str,query:&str,ids:Option<&[String]>,limit:usize)->Result<Vec<Value>,String>{
  let token=source.semantic_mutation_token()?;if token!=self.source_token||!source.pending_search_updates(1)?.is_empty()||source.search_journal_sequence()?!=self.checkpoint{return Err("Поисковый индекс ещё обновляется".into())}
  let db=connect_disposable(&self.file,password)?;let (generation,checkpoint):(String,i64)=db.query_row("SELECT generation,checkpoint FROM atlas_fts_stage_meta WHERE id=1",[],|r|Ok((r.get(0)?,r.get(1)?))).map_err(|_|"Индекс повреждён")?;if generation!=self.generation||checkpoint!=self.checkpoint{return Err("Копия индекса устарела; требуется перестроение".into())}let results=atlas_native_storage_contract::search::lexical(&db,query,ids,limit).map_err(|e|e.to_string())?;
  if source.semantic_mutation_token()?!=token||!source.pending_search_updates(1)?.is_empty(){return Err("Поисковый индекс ещё обновляется".into())}Ok(results)
 }
}
impl Drop for SearchStage { fn drop(&mut self){if std::fs::symlink_metadata(&self.path).is_ok_and(|m|m.is_file()&&(m.dev(),m.ino())==self.owned){let _=std::fs::remove_file(&self.path);}if std::fs::symlink_metadata(&self.lock_path).is_ok_and(|m|m.is_file()&&(m.dev(),m.ino())==self.lock_owned){let _=std::fs::remove_file(&self.lock_path);}if let Some((path,owned))=&self.private_dir{if std::fs::symlink_metadata(path).is_ok_and(|m|m.is_dir()&&(m.dev(),m.ino())==*owned){let _=std::fs::remove_dir(path);}}} }
/// Remove only stages with a durable inode marker and an uncontended lock.
pub fn cleanup_abandoned_stages(dir:&Path)->Result<(),String>{for entry in std::fs::read_dir(dir).map_err(|e|e.to_string())?{let entry=entry.map_err(|e|e.to_string())?;let name=entry.file_name().to_string_lossy().into_owned();let Some(id)=name.strip_prefix(".atlas-search-stage-").and_then(|s|s.strip_suffix(".lock")) else{continue};if id.len()!=32||!id.bytes().all(|b|b.is_ascii_hexdigit()){continue}let lock_path=entry.path();let mut lock=match std::fs::OpenOptions::new().read(true).write(true).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC|libc::O_NONBLOCK).open(&lock_path){Ok(v)=>v,Err(_)=>continue};let lm=lock.metadata().map_err(|e|e.to_string())?;if !lm.is_file()||lm.len()>128||unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_EX|libc::LOCK_NB)}!=0{continue}let mut marker=String::new();if lock.read_to_string(&mut marker).is_err(){continue}let Some((dev,ino))=marker.split_once(':').and_then(|(d,i)|Some((d.parse::<u64>().ok()?,i.parse::<u64>().ok()?))) else{continue};let path=dir.join(format!(".atlas-search-stage-{id}"));match std::fs::symlink_metadata(&path){Ok(m) if m.is_file()&&(m.dev(),m.ino())==(dev,ino)=>std::fs::remove_file(&path).map_err(|e|e.to_string())?,Err(e) if e.kind()==std::io::ErrorKind::NotFound=>{},_=>continue}if std::fs::symlink_metadata(&lock_path).is_ok_and(|m|m.is_file()&&(m.dev(),m.ino())==(lm.dev(),lm.ino())){std::fs::remove_file(lock_path).map_err(|e|e.to_string())?;}}Ok(())}

/// Create an owned private local directory even when the workspace is on a
/// filesystem without Unix permissions. Only encrypted bytes leave this directory.
pub fn build_search_stage_local(source:&Vault,password:&str)->Result<SearchStage,String>{build_search_stage_local_guarded(source,password,||Ok(()))}
pub fn build_search_stage_local_guarded(source:&Vault,password:&str,verify:impl FnMut()->Result<(),String>)->Result<SearchStage,String>{build_search_stage_local_with_generation(source,password,None,verify)}
pub fn build_search_stage_local_with_generation(source:&Vault,password:&str,generation:Option<&str>,verify:impl FnMut()->Result<(),String>)->Result<SearchStage,String>{
 let path=std::env::temp_dir().join(format!("atlas-fts-private-{}",uuid::Uuid::new_v4().simple()));let mut builder=std::fs::DirBuilder::new();builder.mode(0o700);builder.create(&path).map_err(|e|e.to_string())?;
 let meta=std::fs::symlink_metadata(&path).map_err(|e|e.to_string())?;if !meta.is_dir()||meta.uid()!=unsafe{libc::geteuid()}||meta.mode()&0o077!=0{return Err("Не удалось создать приватную папку индекса".into())}let owned=(meta.dev(),meta.ino());
 match build_search_stage_with(source,&path,password,generation,verify){Ok(mut stage)=>{stage.private_dir=Some((path,owned));Ok(stage)},Err(e)=>{if std::fs::symlink_metadata(&path).is_ok_and(|m|m.is_dir()&&(m.dev(),m.ino())==owned){let _=std::fs::remove_dir(&path);}Err(e)}}
}

/// Builds only an unpublished SQLCipher file. `dir` must be a private staging
/// directory; exclusive creation ensures an existing user file is never replaced.
pub fn build_search_stage(source:&Vault,dir:&Path,password:&str)->Result<SearchStage,String>{build_search_stage_with(source,dir,password,None,||Ok(()))}
pub fn build_search_stage_guarded(source:&Vault,dir:&Path,password:&str,verify:impl FnMut()->Result<(),String>)->Result<SearchStage,String>{build_search_stage_with(source,dir,password,None,verify)}
pub fn build_search_stage_with_generation(source:&Vault,dir:&Path,password:&str,generation:&str,verify:impl FnMut()->Result<(),String>)->Result<SearchStage,String>{build_search_stage_with(source,dir,password,Some(generation),verify)}
fn build_search_stage_with(source:&Vault,dir:&Path,password:&str,requested_generation:Option<&str>,mut verify:impl FnMut()->Result<(),String>)->Result<SearchStage,String>{
 if password.is_empty(){return Err("Укажите пароль".into())}
 source.pending_search_updates(1)?;
 let source_identity=source.workspace_identity()?;let source_token=source.semantic_mutation_token()?;let checkpoint=source.search_journal_sequence()?;
 let generation=requested_generation.map(str::to_owned).unwrap_or_else(||uuid::Uuid::new_v4().simple().to_string());if generation.len()!=32||!generation.bytes().all(|b|b.is_ascii_hexdigit()){return Err("Некорректное поколение индекса".into())}let path=dir.join(format!(".atlas-search-stage-{generation}"));
 let lock_path=path.with_file_name(format!("{}.lock",path.file_name().ok_or("invalid path")?.to_string_lossy()));
 let mut lock=std::fs::OpenOptions::new().read(true).write(true).create_new(true).mode(0o600).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC).open(&lock_path).map_err(|e|e.to_string())?;if unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_EX|libc::LOCK_NB)}!=0{return Err("Не удалось заблокировать индекс".into())}let lm=lock.metadata().map_err(|e|e.to_string())?;
 let file=std::fs::OpenOptions::new().read(true).write(true).create_new(true).mode(0o600).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC).open(&path).map_err(|e|e.to_string())?;
 let meta=file.metadata().map_err(|e|e.to_string())?;let stage=SearchStage{path,source_token,generation,checkpoint,owned:(meta.dev(),meta.ino()),lock_path,lock_owned:(lm.dev(),lm.ino()),_lock:lock.try_clone().map_err(|e|e.to_string())?,file:file.try_clone().map_err(|e|e.to_string())?,published:std::sync::atomic::AtomicBool::new(false),private_dir:None};write!(lock,"{}:{}",meta.dev(),meta.ino()).map_err(|e|e.to_string())?;lock.sync_all().map_err(|e|e.to_string())?;
 #[cfg(feature="test-hook")] if let Some(dir)=std::env::var_os("ATLAS_TEST_SEARCH_STAGE_OPEN_BARRIER"){let dir=Path::new(&dir);std::fs::write(dir.join("open-ready"),stage.path.file_name().ok_or("invalid stage")?.as_encoded_bytes()).map_err(|e|e.to_string())?;while !dir.join("open-go").exists(){std::thread::sleep(std::time::Duration::from_millis(10));}}
 verify()?;let db=connect_disposable(&stage.file,password)?;
 db.execute_batch("CREATE TABLE objects(id TEXT PRIMARY KEY,title TEXT NOT NULL); CREATE TABLE trash(id TEXT PRIMARY KEY); CREATE TABLE atlas_fts_applied(id TEXT PRIMARY KEY,generation INTEGER NOT NULL); CREATE VIRTUAL TABLE search_index USING fts5(id UNINDEXED,title,body,description); CREATE VIRTUAL TABLE search_chunks USING fts5(object_id UNINDEXED,start UNINDEXED,field UNINDEXED,content,tokenize='unicode61');").map_err(|e|e.to_string())?;
 let source_schema:String=source.db.query_row("SELECT sql FROM sqlite_master WHERE name='search_index'",[],|r|r.get(0)).map_err(|e|e.to_string())?;
 let regenerate_chunks=!source_schema.trim_start().to_ascii_uppercase().starts_with("CREATE VIRTUAL TABLE");
 for (table,columns) in [("search_index","id,title,body,description"),("search_chunks","object_id,start,field,content")] {
  if table=="search_chunks"&&regenerate_chunks{continue}
  let mut cursor=0i64;
  loop {
   let sql=format!("SELECT rowid,{columns} FROM {table} WHERE rowid>?1 ORDER BY rowid LIMIT 1");
   use rusqlite::OptionalExtension;
   let row:Option<(i64,rusqlite::types::Value,rusqlite::types::Value,rusqlite::types::Value,rusqlite::types::Value)>=source.db.query_row(&sql,[cursor],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?,r.get(4)?))).optional().map_err(|e|e.to_string())?;
   let Some((id,a,b,c,d))=row else{break};cursor=id;
   let sql=format!("INSERT INTO {table}({columns}) VALUES(?1,?2,?3,?4)");verify()?;db.execute(&sql,rusqlite::params![&a,&b,&c,&d]).map_err(|e|e.to_string())?;
   if table=="search_index"&&regenerate_chunks {let (id,title,body,description)=match (&a,&b,&c,&d){(rusqlite::types::Value::Text(id),rusqlite::types::Value::Text(title),rusqlite::types::Value::Text(body),rusqlite::types::Value::Text(description))=>(id,title,body,description),_=>return Err("Некорректный исходный текст".into())};db.execute("INSERT INTO search_chunks VALUES(?1,-1,'title',?2)",params![id,title]).map_err(|e|e.to_string())?;for(field,text)in [("body",body.as_str()),("description",description.as_str())]{for(start,part)in chunks(text){verify()?;db.execute("INSERT INTO search_chunks VALUES(?1,?2,?3,?4)",params![id,start as i64,field,part]).map_err(|e|e.to_string())?;}}}
   #[cfg(feature="test-hook")] if let Some(dir)=std::env::var_os("ATLAS_TEST_SEARCH_STAGE_BARRIER"){let dir=Path::new(&dir);std::fs::write(dir.join("ready"),stage.path.file_name().ok_or("invalid stage")?.as_encoded_bytes()).map_err(|e|e.to_string())?;while !dir.join("go").exists(){std::thread::sleep(std::time::Duration::from_millis(10));}}verify()?;
   if source.semantic_mutation_token()?!=source_token{return Err("Пространство изменилось во время подготовки поиска".into())}
  }
 }
 for (table,sql) in [("objects","SELECT rowid,id,title FROM objects WHERE rowid>?1 ORDER BY rowid LIMIT 1"),("trash","SELECT rowid,id,'' FROM trash WHERE rowid>?1 ORDER BY rowid LIMIT 1")]{let mut cursor=0i64;loop{use rusqlite::OptionalExtension;let row:Option<(i64,String,String)>=source.db.query_row(sql,[cursor],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).optional().map_err(|e|e.to_string())?;let Some((rowid,id,title))=row else{break};cursor=rowid;verify()?;if table=="objects"{db.execute("INSERT INTO objects VALUES(?1,?2)",params![id,title]).map_err(|e|e.to_string())?;}else{db.execute("INSERT INTO trash VALUES(?1)",[id]).map_err(|e|e.to_string())?;}if source.semantic_mutation_token()?!=source_token{return Err("Пространство изменилось во время подготовки поиска".into())}}}
 if source.semantic_mutation_token()?!=source_token{return Err("Пространство изменилось во время подготовки поиска".into())}
 let current=std::fs::symlink_metadata(stage.path()).map_err(|e|e.to_string())?;if !current.is_file()||(current.dev(),current.ino())!=stage.owned{return Err("Файл индекса изменился".into())}
 verify()?;let check:String=db.query_row("PRAGMA quick_check",[],|r|r.get(0)).map_err(|e|e.to_string())?;if check!="ok"{return Err("Подготовленный индекс повреждён".into())}
 verify()?;db.execute_batch("CREATE TABLE atlas_fts_stage_meta(id INTEGER PRIMARY KEY CHECK(id=1),complete INTEGER NOT NULL,source_identity TEXT NOT NULL,generation TEXT NOT NULL,checkpoint INTEGER NOT NULL);").map_err(|e|e.to_string())?;db.execute("INSERT INTO atlas_fts_stage_meta VALUES(1,1,?1,?2,?3)",params![source_identity,stage.generation,stage.checkpoint]).map_err(|e|e.to_string())?;
 if source.semantic_mutation_token()?!=source_token{return Err("Пространство изменилось во время подготовки поиска".into())}
 verify()?;let mode:String=db.query_row("PRAGMA journal_mode=DELETE",[],|r|r.get(0)).map_err(|e|e.to_string())?;if !mode.eq_ignore_ascii_case("delete"){return Err("Не удалось подготовить журнал индекса".into())}drop(db);file.sync_all().map_err(|e|e.to_string())?;Ok(stage)
}

#[cfg(test)] mod tests {
 use super::*;
 #[test] fn guarded_replay_preserves_queue_when_medium_disappears() {
  let root=std::env::temp_dir().join(format!("atlas-replay-guard-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut source=Vault::create(&root.join("source.atlas"),"password").unwrap();source.enable_search_journal().unwrap();source.put_note("n","title","before").unwrap();let mut stage=build_search_stage(&source,&root,"password").unwrap();let calls=std::cell::Cell::new(0);let result=stage.replay_pending_guarded(&source,"password",256,||{let n=calls.get()+1;calls.set(n);if n>=2{Err("medium disconnected".into())}else{Ok(())}});assert!(result.is_err());assert!(!source.pending_search_updates(1).unwrap().is_empty());assert_eq!(stage.replay_pending(&source,"password",256).unwrap(),1);drop(stage);drop(source);std::fs::remove_dir_all(root).unwrap();
 }
 #[test] fn guarded_build_cancels_and_keeps_source() {
  let root=std::env::temp_dir().join(format!("atlas-stage-cancel-{}",uuid::Uuid::new_v4()));
  std::fs::create_dir(&root).unwrap();
  let mut source=Vault::create(&root.join("source.atlas"),"password").unwrap();
  source.enable_search_journal().unwrap();
  source.put_note("n","note","content remains").unwrap();
  let mut calls=0;
  let result=build_search_stage_guarded(&source,&root,"password",||{calls+=1;if calls==3 {Err("cancelled".into())}else{Ok(())}});
  assert!(result.is_err());
  assert_eq!(source.db.query_row("SELECT body FROM search_index WHERE id='n'",[],|r|r.get::<_,String>(0)).unwrap(),"content remains");
  assert_eq!(std::fs::read_dir(&root).unwrap().filter_map(Result::ok).filter(|e|e.file_name().to_string_lossy().starts_with(".atlas-search-stage-")).count(),0);
  drop(source);std::fs::remove_dir_all(root).unwrap();
 }
 #[test] fn stage_is_encrypted_and_does_not_publish(){let root=std::env::temp_dir().join(format!("atlas-search-stage-test-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("source.atlas"),"password").unwrap();v.enable_search_journal().unwrap();let marker="PRIVATE_TEST_SEARCH_TOKEN_d4e551";v.put_note("n","note",marker).unwrap();let stage=build_search_stage(&v,&root,"password").unwrap();let bytes=std::fs::read(stage.path()).unwrap();assert!(!bytes.windows(marker.len()).any(|w|w==marker.as_bytes()));let wrong=Vault::connect(stage.path(),"wrong-password").unwrap();assert!(wrong.query_row("SELECT count(*) FROM search_index",[],|r|r.get::<_,i64>(0)).is_err());drop(wrong);let db=Vault::connect(stage.path(),"password").unwrap();let text:String=db.query_row("SELECT body FROM search_index WHERE id='n'",[],|r|r.get(0)).unwrap();assert_eq!(text,marker);drop(db);let path=stage.path().to_owned();drop(stage);assert!(!path.exists());drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn orphan_cleanup_preserves_live_stage_and_unowned_files(){use std::io::Write;let root=std::env::temp_dir().join(format!("atlas-search-stage-cleanup-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("source.atlas"),"password").unwrap();v.enable_search_journal().unwrap();v.put_note("n","note","body").unwrap();let stage=build_search_stage(&v,&root,"password").unwrap();let path=stage.path().to_owned();cleanup_abandoned_stages(&root).unwrap();assert!(path.exists());let id=uuid::Uuid::new_v4().simple().to_string();let orphan=root.join(format!(".atlas-search-stage-{id}"));std::fs::write(&orphan,b"encrypted orphan").unwrap();let meta=std::fs::metadata(&orphan).unwrap();let lock=root.join(format!(".atlas-search-stage-{id}.lock"));let mut f=std::fs::File::create(&lock).unwrap();write!(f,"{}:{}",meta.dev(),meta.ino()).unwrap();drop(f);let foreign=root.join(format!(".atlas-search-stage-{}",uuid::Uuid::new_v4().simple()));std::fs::write(&foreign,b"user file").unwrap();cleanup_abandoned_stages(&root).unwrap();assert!(!orphan.exists());assert!(!lock.exists());assert!(foreign.exists());assert!(path.exists());drop(stage);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn replay_retries_after_crash_without_losing_newer_edits(){let root=std::env::temp_dir().join(format!("atlas-search-stage-replay-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("source.atlas"),"password").unwrap();v.enable_search_journal().unwrap();v.put_note("n","note","before").unwrap();let mut stage=build_search_stage(&v,&root,"password").unwrap();for (id,generation) in v.pending_search_updates(256).unwrap(){v.acknowledge_search_update(&id,generation).unwrap();}v.put_note("n","note","after").unwrap();assert!(stage.replay_pending_with(&v,"password",256,||Err("injected crash".into())).is_err());assert_eq!(v.pending_search_updates(256).unwrap().len(),1);v.put_note("n","note","latest").unwrap();assert_eq!(stage.replay_pending(&v,"password",256).unwrap(),1);assert!(v.pending_search_updates(256).unwrap().is_empty());let db=Vault::connect(stage.path(),"password").unwrap();let text:String=db.query_row("SELECT body FROM search_index WHERE id='n'",[],|r|r.get(0)).unwrap();assert_eq!(text,"latest");drop(db);drop(stage);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn publish_requires_empty_journal_and_never_overwrites(){let root=std::env::temp_dir().join(format!("atlas-search-stage-publish-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("source.atlas"),"password").unwrap();v.enable_search_journal().unwrap();v.put_note("n","note","before").unwrap();let mut stage=build_search_stage(&v,&root,"password").unwrap();let target=root.join("workspace.search.atlas");assert!(stage.publish(&v,&target,||Ok(())).is_err());assert!(!target.exists());assert_eq!(stage.replay_pending(&v,"password",256).unwrap(),1);stage.publish(&v,&target,||Ok(())).unwrap();let original=std::fs::read(&target).unwrap();stage.publish(&v,&target,||Ok(())).unwrap();assert_eq!(std::fs::read(&target).unwrap(),original);let foreign=root.join("existing.atlas");std::fs::write(&foreign,b"keep").unwrap();assert!(stage.publish(&v,&foreign,||Ok(())).is_err());assert_eq!(std::fs::read(&foreign).unwrap(),b"keep");let db=Vault::connect(&target,"password").unwrap();let text:String=db.query_row("SELECT body FROM search_index WHERE id='n'",[],|r|r.get(0)).unwrap();assert_eq!(text,"before");drop(db);drop(stage);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn derived_search_matches_source_and_never_returns_stale_results(){let root=std::env::temp_dir().join(format!("atlas-derived-search-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("source.atlas"),"password").unwrap();v.enable_search_journal().unwrap();v.put_note("a","one","слово полезная информация").unwrap();v.put_note("b","two","слово другое").unwrap();let mut stage=build_search_stage(&v,&root,"password").unwrap();assert!(stage.search(&v,"password","слово",None,10).is_err());while !v.pending_search_updates(1).unwrap().is_empty(){stage.replay_pending(&v,"password",256).unwrap();}let expected=v.search_chunks("слово",None,10).unwrap();let actual=stage.search(&v,"password","слово",None,10).unwrap();assert_eq!(actual,expected);v.trash_many(&["a".into()],0).unwrap();assert!(stage.search(&v,"password","слово",None,10).is_err());stage.replay_pending(&v,"password",256).unwrap();let visible=stage.search(&v,"password","слово",None,10).unwrap();assert!(visible.iter().all(|r|r["id"]!="a"));v.restore_many(&["a".into()]).unwrap();stage.replay_pending(&v,"password",256).unwrap();assert_eq!(stage.search(&v,"password","слово",None,10).unwrap(),v.search_chunks("слово",None,10).unwrap());drop(stage);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn replay_never_clears_edit_committed_between_secondary_commit_and_ack(){let root=std::env::temp_dir().join(format!("atlas-search-ack-race-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let path=root.join("source.atlas");let mut v=Vault::create(&path,"password").unwrap();v.enable_search_journal().unwrap();v.put_note("n","note","before").unwrap();let mut stage=build_search_stage(&v,&root,"password").unwrap();let mut other=Vault::open(&path,"password").unwrap();let mut changed=false;assert_eq!(stage.replay_pending_with(&v,"password",256,||{if !changed{other.put_note("n","note","newer").unwrap();changed=true}Ok(())}).unwrap(),1);assert!(!v.pending_search_updates(1).unwrap().is_empty());assert!(stage.search(&v,"password","newer",None,10).is_err());assert_eq!(stage.replay_pending(&v,"password",256).unwrap(),1);let result=stage.search(&v,"password","newer",None,10).unwrap();assert_eq!(result.len(),1);drop(other);drop(stage);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn rebuild_after_primary_cutover_regenerates_chunks(){let root=std::env::temp_dir().join(format!("atlas-derived-rebuild-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("source.atlas"),"password").unwrap();v.enable_search_journal().unwrap();v.put_note("n","Title","слово полезная информация").unwrap();for (id,generation) in v.pending_search_updates(10).unwrap(){v.acknowledge_search_update(&id,generation).unwrap();}let expected=v.search_chunks("слово",None,10).unwrap();v.db.execute_batch("ALTER TABLE search_index RENAME TO old_search_index; CREATE TABLE search_index(id TEXT PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,description TEXT NOT NULL); INSERT INTO search_index SELECT * FROM old_search_index; DELETE FROM search_chunks;").unwrap();let stage=build_search_stage(&v,&root,"password").unwrap();assert_eq!(stage.search(&v,"password","слово",None,10).unwrap(),expected);drop(stage);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn published_search_checks_identity_and_refuses_dirty_journal(){let root=std::env::temp_dir().join(format!("atlas-search-published-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("source.atlas"),"password").unwrap();v.enable_search_journal().unwrap();v.put_note("n","note","before").unwrap();let mut stage=build_search_stage(&v,&root,"password").unwrap();stage.replay_pending(&v,"password",256).unwrap();let target=root.join("workspace.search.atlas");stage.publish(&v,&target,||Ok(())).unwrap();let identity=v.workspace_identity().unwrap();v.db.execute_batch("CREATE TABLE atlas_fts_active(singleton INTEGER PRIMARY KEY,source_identity TEXT NOT NULL,generation TEXT NOT NULL,checkpoint INTEGER NOT NULL)").unwrap();v.db.execute("INSERT INTO atlas_fts_active VALUES(1,?1,?2,?3)",params![&identity,stage.generation(),stage.checkpoint()]).unwrap();assert_eq!(search_published(&v,&target,"password","before",None,10).unwrap().len(),1);v.put_note("n","note","after").unwrap();assert!(search_published(&v,&target,"password","before",None,10).is_err());{let db=Vault::connect(&target,"password").unwrap();replay_pending_db(&v,&db,256).unwrap();}assert_eq!(search_published(&v,&target,"password","after",None,10).unwrap().len(),1);v.db.execute("UPDATE atlas_fts_active SET source_identity='other'",[]).unwrap();assert!(search_published(&v,&target,"password","after",None,10).is_err());drop(stage);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn restored_old_secondary_copy_is_never_accepted(){let root=std::env::temp_dir().join(format!("atlas-search-old-copy-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("source.atlas"),"password").unwrap();v.enable_search_journal().unwrap();v.put_note("n","note","first").unwrap();let mut stage=build_search_stage(&v,&root,"password").unwrap();stage.replay_pending(&v,"password",256).unwrap();let target=root.join("workspace.search.atlas");stage.publish(&v,&target,||Ok(())).unwrap();let old=std::fs::read(&target).unwrap();let identity=v.workspace_identity().unwrap();v.db.execute_batch("CREATE TABLE atlas_fts_active(singleton INTEGER PRIMARY KEY,source_identity TEXT NOT NULL,generation TEXT NOT NULL,checkpoint INTEGER NOT NULL)").unwrap();v.db.execute("INSERT INTO atlas_fts_active VALUES(1,?1,?2,?3)",params![identity,stage.generation(),stage.checkpoint()]).unwrap();v.put_note("n","note","newword").unwrap();{let db=Vault::connect(&target,"password").unwrap();replay_pending_db(&v,&db,256).unwrap();}assert_eq!(search_published(&v,&target,"password","newword",None,10).unwrap().len(),1);std::fs::write(&target,old).unwrap();assert!(search_published(&v,&target,"password","newword",None,10).is_err());assert!(stage.search(&v,"password","newword",None,10).is_err());assert!(stage.synchronize_checkpoint(&v,"password").is_err());assert!(search_published(&v,&target,"password","newword",None,10).is_err());drop(stage);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn partial_batches_keep_entire_journal_until_all_are_durable(){let root=std::env::temp_dir().join(format!("atlas-search-batch-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("source.atlas"),"password").unwrap();v.enable_search_journal().unwrap();for id in ["a","b","c"]{v.put_note(id,id,"word").unwrap()}let mut stage=build_search_stage(&v,&root,"password").unwrap();assert_eq!(stage.replay_pending(&v,"password",1).unwrap(),1);assert_eq!(v.all_pending_search_updates().unwrap().len(),3);assert!(stage.search(&v,"password","word",None,10).is_err());assert_eq!(stage.replay_pending(&v,"password",1).unwrap(),1);assert_eq!(v.all_pending_search_updates().unwrap().len(),3);assert_eq!(stage.replay_pending(&v,"password",1).unwrap(),1);assert!(v.all_pending_search_updates().unwrap().is_empty());assert_eq!(stage.search(&v,"password","word",None,10).unwrap().len(),3);drop(stage);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn old_secondary_restored_after_interrupted_replay_is_replayed_not_trusted(){let root=std::env::temp_dir().join(format!("atlas-search-interrupted-copy-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("source.atlas"),"password").unwrap();v.enable_search_journal().unwrap();v.put_note("n","note","first").unwrap();let mut stage=build_search_stage(&v,&root,"password").unwrap();stage.replay_pending(&v,"password",256).unwrap();let old=std::fs::read(stage.path()).unwrap();v.put_note("n","note","newword").unwrap();assert!(stage.replay_pending_with(&v,"password",256,||Err("crash".into())).is_err());assert!(!v.pending_search_updates(1).unwrap().is_empty());std::fs::write(stage.path(),old).unwrap();assert!(stage.search(&v,"password","newword",None,10).is_err());assert_eq!(stage.replay_pending(&v,"password",256).unwrap(),1);assert_eq!(stage.search(&v,"password","newword",None,10).unwrap().len(),1);drop(stage);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn concurrent_source_mutation_discards_stage(){let root=std::env::temp_dir().join(format!("atlas-search-stage-race-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let path=root.join("source.atlas");let mut writer=Vault::create(&path,"password").unwrap();writer.enable_search_journal().unwrap();writer.put_note("n","note","before").unwrap();let source=Vault::open(&path,"password").unwrap();let mut changed=false;let result=build_search_stage_with(&source,&root,"password",None,||{if !changed{writer.put_note("n","note","after").unwrap();changed=true}Ok(())});assert!(result.is_err());assert!(!std::fs::read_dir(&root).unwrap().any(|e|e.unwrap().file_name().to_string_lossy().starts_with(".atlas-search-stage-")));drop(source);drop(writer);std::fs::remove_dir_all(root).unwrap();}
}

/// Query a published derived index only when its durable source journal is empty.
/// The caller must serialize ordinary primary-Vault mutations during the check;
/// commits from other connections are detected by data_version after the query.
pub fn search_published(source:&Vault,path:&Path,password:&str,query:&str,ids:Option<&[String]>,limit:usize)->Result<Vec<Value>,String>{
 let meta=std::fs::symlink_metadata(path).map_err(|_|"Поисковый индекс недоступен")?;if !meta.is_file(){return Err("Поисковый индекс недоступен".into())}
 let db=Vault::connect(path,password)?;search_published_db(source,&db,query,ids,limit)
}
/// Same stale-safe check using an already opened secondary SQLCipher connection.
/// The caller must pin and validate the secondary file identity separately.
pub fn search_published_db(source:&Vault,db:&Connection,query:&str,ids:Option<&[String]>,limit:usize)->Result<Vec<Value>,String>{
 let token=source.semantic_mutation_token()?;
 if !source.pending_search_updates(1)?.is_empty(){return Err("Поисковый индекс ещё обновляется".into())}
 let (expected,generation,checkpoint):(String,String,i64)=source.db.query_row("SELECT source_identity,generation,checkpoint FROM atlas_fts_active WHERE singleton=1",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|_|"Поисковый индекс не активирован")?;
 if checkpoint!=source.search_journal_sequence()?{return Err("Поисковый индекс ещё обновляется".into())}
 if expected!=source.workspace_identity()?{return Err("Поисковый индекс относится к другому пространству".into())}
 let (complete,identity,derived_generation,derived_checkpoint):(i64,String,String,i64)=db.query_row("SELECT complete,source_identity,generation,checkpoint FROM atlas_fts_stage_meta WHERE id=1",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?))).map_err(|_|"Поисковый индекс повреждён")?;
 if complete!=1||identity!=expected||derived_generation!=generation||derived_checkpoint!=checkpoint{return Err("Поисковый индекс относится к другому пространству или устарел".into())}
 let scope=source.search_scope(ids.map(|items|items.to_vec()))?;
 let results=atlas_native_storage_contract::search::lexical(db,query,scope.as_deref(),limit).map_err(|e|e.to_string())?;
 if source.semantic_mutation_token()?!=token||!source.pending_search_updates(1)?.is_empty(){return Err("Поисковый индекс ещё обновляется".into())}Ok(results)
}
